// Package nativemirror manages the per-(repo group, cluster) native-mirror
// placements of native repos (ADR 20260720-native-mirroring). A row is
// both the placement record and the durable cross-jurisdiction creation
// intent: the primary jurisdiction's core writes it, and the target
// jurisdiction's lifecycle reconciler claims and executes it through the
// stage machine (pending → provisioned → registered → seeded → announced)
// or, when desired_state flips to 'deleted', through the teardown leg.
//
// Concurrency model: CockroachDB has no advisory locks, so exclusivity is a
// row lease — Claim is a single UPDATE ... RETURNING that stamps
// claimed_by/claimed_at and bumps attempts (the mirror_author_backfills
// pattern), and every subsequent transition is fenced on claimed_by AND
// CAS'd on the fields it advances, so an executor whose lease expired and
// was reclaimed cannot rewrite the new owner's row. A failed CAS is a
// signal to re-read: teardown is intended only when desired_state says so;
// an active row whose stage moved means another executor won.
package nativemirror

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"entire.io/core/model"
	"entire.io/core/repodeletion"
	"entire.io/postgres"
)

// Creation stages. Ordered; StagesServing lists the suffix from which a
// placement is serving-eligible (replication fan-out, resync sweep,
// completion-status writes).
const (
	StagePending     = "pending"
	StageProvisioned = "provisioned"
	StageRegistered  = "registered"
	StageSeeded      = "seeded"
	StageAnnounced   = "announced"
)

// Clone-lifecycle status, mirroring mirrorrepo's vocabulary so placement
// views render both kinds with one legend. StatusFailed doubles as the
// permanently-failed-creation marker (next_retry_at NULL).
const (
	StatusProcessing = "processing"
	StatusReady      = "ready"
	StatusFailed     = "failed"
	StatusSuspended  = "suspended"
)

// Deletion intent. DELETE flips desired_state and stamps suspended_at; the
// reconciler's teardown leg does the actual work.
const (
	DesiredActive  = "active"
	DesiredDeleted = "deleted"
)

// servingStages is the SQL fragment for "stage >= registered". The stage
// set is fixed; enumerating beats encoding an ordinal.
const servingStages = `('registered', 'seeded', 'announced')`

// completionEligible is the intent gate a worker completion must clear: a
// serving-eligible, active, unsuspended placement whose creation has not
// permanently failed. Shared by BOTH arms of ApplyCompletionStatus so the
// 'ready' and 'failed' paths can never drift on eligibility — a new lifecycle
// column added to one arm only would honor a completion for a placement the
// other arm refuses.
//
// Parenthesised so it stays safe by construction rather than by call-site
// convention: it is a bare AND chain, so splicing it unparenthesised into a
// predicate that has a same-level OR would silently regroup and WIDEN which
// placements accept a completion — the over-claim direction.
const completionEligible = `(stage IN ` + servingStages + `
		   AND desired_state = 'active' AND suspended_at IS NULL
		   AND creation_failed_at IS NULL)`

// ErrNotFound is returned by point reads when no row matches.
var ErrNotFound = errors.New("nativemirror: not found")

// ErrBeingDeleted is returned by Create when the (group, cluster) placement
// exists but is marked for deletion: the returned id would be reaped by the
// teardown leg moments later, so "resume the existing intent" is a lie for
// this state. Callers surface it as a retry-later conflict; re-creating
// becomes possible once teardown removes the row.
var ErrBeingDeleted = errors.New("nativemirror: placement is being deleted")

// ErrCellOccupied is returned when another cluster already holds a placement in the target cell.
var ErrCellOccupied = errors.New("nativemirror: target cell is occupied")

// ErrCellVacating is returned when only placements marked for deletion hold
// the target cell. The cell frees when teardown removes their rows, so a
// caller can retry.
var ErrCellVacating = errors.New("nativemirror: target cell is being vacated")

// ErrPlacementCellUnknown is returned when registry data cannot establish cell occupancy.
var ErrPlacementCellUnknown = errors.New("nativemirror: placement cell unavailable")

// ErrGroupBeingDeleted is returned when creation loses the serialization race
// with deletion of the primary repo. Both paths lock the repo_group row, and
// the standing delete_pending_at tombstone remains set until primary teardown
// completes, so a create can never land behind an accepted primary delete.
var ErrGroupBeingDeleted = errors.New("nativemirror: primary repo is being deleted")

// ErrPrimaryHasNativeMirrors is returned when an interactive/admin primary
// delete finds LIVE placement rows (desired_state='active'). Those callers must
// delete the mirrors first; account erasure uses BeginPrimaryErasure to mark
// them and converge in passes.
var ErrPrimaryHasNativeMirrors = errors.New("nativemirror: primary repo still has native mirrors")

// ErrPrimaryNativeMirrorsDraining is returned when an interactive/admin primary
// delete finds only placements already marked for teardown. No user action is
// left: the mirrors ARE deleted, and DELETE on one is idempotent. So the
// caller must report progress, not the conflict above, whose advice cannot be
// followed (COR-1626).
var ErrPrimaryNativeMirrorsDraining = errors.New("nativemirror: primary repo's native mirrors are still draining")

