package nativemirror

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/url"
	"time"

	"entire.io/core/cluster"
	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/core/registry"
	"entire.io/core/repoadmin"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
)

// The executor drives creation and teardown in the placement's jurisdiction.
// Every external step on both legs is idempotent, so a reclaimed row resumes
// from recorded state after a crash or lease loss. Creation is stage-CAS'd;
// teardown is selected by durable desired_state and retains the row as its
// retry anchor until every placement-owned resource has been removed.

// ExecutorRegistry is the resource-store slice the executor uses;
// resource.Service satisfies it. The registry publish is on RegistryPublisher.
type ExecutorRegistry interface {
	GetRepoRegistration(ctx context.Context, repoID model.RepoID) (*model.RepoRegistration, error)
	GetProject(ctx context.Context, projectID model.ProjectID) (*model.Project, error)
	UnpublishRepo(ctx context.Context, repoID model.RepoID) error
}

// ExecutorProvisioner is the core→data-plane Provision slice the executor
// dispatches through. api.RepoBridge (repoadmin.Router in production)
// satisfies it.
type ExecutorProvisioner interface {
	Provision(ctx context.Context, clusterSlug string, params model.ProvisionParams) error
	Delete(ctx context.Context, repoID model.RepoID, clusterSlug string) (repoadmin.DeleteResult, error)
}

// ExecutorAuthz links placements to their group and removes placement relationships on teardown.
// authz.Service satisfies it.
type ExecutorAuthz interface {
	NativeMirrorPlacementRegistered(ctx context.Context, mirrorID model.RepoID, groupID model.RepoGroupID) error
	NativeMirrorPlacementDeleted(ctx context.Context, mirrorID model.RepoID) error
}

// ExecutorSeeder publishes the placement's initial entiredb-kind sync job.
// *gitjobs.Publisher satisfies it.
type ExecutorSeeder interface {
	PublishEntireDBSyncRepo(ctx context.Context, placement gitjobs.Placement, source gitjobs.Source, target gitjobs.Target) error
}

// ExecutorClusters resolves cluster rows — the data primary's home (internal
// fetch URL). *cluster.Store satisfies it.
type ExecutorClusters interface {
	GetBySlugGlobal(ctx context.Context, slug string) (*cluster.Cluster, error)
}

// ExecutorLifecycle publishes placement lifecycle projections consumed by
// entire-api. *resourceevents.Emitter satisfies it. Publish is the shared
// best-effort contract; on both legs it is only the low-latency attempt, with
// durability owned by a same-transaction outbox row a relay republishes
// through PubAck — the deletion outbox on teardown (COR-1049) and the created
// outbox on the seeded→announced announce (COR-1359).
type ExecutorLifecycle interface {
	Publish(ctx context.Context, resourceType, resourceID, op, actorID string, opts ...resourceevents.PublishOption)
}

// ExecutorConfig tunes one executor instance.
type ExecutorConfig struct {
	// Jurisdiction scopes claims: only intents whose target cluster lives
	// here are eligible (the Claim SQL joins clusters on it). Required.
	Jurisdiction string
	// ClaimedBy fences every stage transition on this identity (the pod
	// name in production). Required.
	ClaimedBy string
	// Interval between claim attempts; a successful claim immediately
	// re-polls so a backlog drains at execution speed, not tick speed.
	// Default 15s.
	Interval time.Duration
	// Lease is the claim's validity; an expired lease makes the row
	// reclaimable (crashed executor). Default DefaultClaimLease.
	Lease time.Duration
	// RetryBackoff spaces re-claims of a row whose execution errored.
	// Default 30s.
	RetryBackoff time.Duration
	// MaxCreationAttempts caps how many times a creation is retried before it
	// is marked permanently failed (status=failed, creation_failed_at set) so
	// it stops re-claiming and surfaces on the status API. A validation-class
	// error fails immediately regardless of count. Teardown is never capped —
	// it must converge for account erasure. Default 20.
	MaxCreationAttempts int64
	// StuckThreshold is the attempt count past which a still-failing row emits
	// an escalation log/metric. It does not change control flow; it exists so a
	// teardown that cannot converge (which would block account-erasure
	// draining indefinitely, since teardown is never capped) is observable
	// rather than silent. Default 10.
	StuckThreshold int64
}

func (c ExecutorConfig) withDefaults() ExecutorConfig {
	if c.Interval <= 0 {
		c.Interval = 15 * time.Second
	}
	if c.Lease <= 0 {
		c.Lease = DefaultClaimLease
	}
	if c.RetryBackoff <= 0 {
		c.RetryBackoff = 30 * time.Second
	}
	if c.MaxCreationAttempts <= 0 {
		c.MaxCreationAttempts = 20
	}
	if c.StuckThreshold <= 0 {
		c.StuckThreshold = 10
	}
	return c
}

// errPermanentCreation classifies a creation failure that retrying cannot
// resolve (a validation-class error on immutable intent state). RunOnce marks
// such a row permanently failed on the first occurrence instead of hot-looping
// it to the attempts cap.
var errPermanentCreation = errors.New("permanent creation failure")

// errRetryUncapped classifies a creation-step failure that must retry
// indefinitely, exempt from MaxCreationAttempts. Used for the entire
// seeded→announced announce step (project load, event marshal, the terminal
// CAS+enqueue transaction): at that point every resource is built and
// replicating, so permanently failing the row is pure loss — a routine
// database or registry outage longer than cap×backoff (~10 minutes at the
// defaults) would otherwise mass-convert finished creations into permanent
// failures that nothing heals (the resync sweep repairs sync lag on serving
// placements; it never re-announces, and permafailed rows are dropped from
// serving). Rows held here past StuckThreshold attempts emit the same
// escalation signal as a stuck teardown.
var errRetryUncapped = errors.New("retryable outside the attempts cap")

