// Executor drives native-mirror creation intents in one jurisdiction.
type Executor struct {
	intents  *Service
	registry ExecutorRegistry
	bridge   ExecutorProvisioner
	authz    ExecutorAuthz
	seeder   ExecutorSeeder
	clusters ExecutorClusters
	events   ExecutorLifecycle
	cfg      ExecutorConfig
	// stageAges tracks emitted stage-age series so a drained combination is
	// zeroed once (see stageAgeSeries). Zero value is ready to use.
	stageAges stageAgeSeries
}

// NewExecutor wires an Executor. Every dep is required; the constructor
// errors on gaps so serve-mode boot fails loudly rather than the executor
// nil-panicking mid-claim.
func NewExecutor(intents *Service, registry ExecutorRegistry, bridge ExecutorProvisioner, authz ExecutorAuthz, seeder ExecutorSeeder, clusters ExecutorClusters, events ExecutorLifecycle, cfg ExecutorConfig) (*Executor, error) {
	switch {
	case intents == nil:
		return nil, errors.New("nativemirror executor: intents store is nil")
	case registry == nil:
		return nil, errors.New("nativemirror executor: registry is nil")
	case bridge == nil:
		return nil, errors.New("nativemirror executor: provision bridge is nil")
	case authz == nil:
		return nil, errors.New("nativemirror executor: authz is nil")
	case seeder == nil:
		return nil, errors.New("nativemirror executor: seed publisher is nil")
	case clusters == nil:
		return nil, errors.New("nativemirror executor: cluster store is nil")
	case events == nil:
		return nil, errors.New("nativemirror executor: lifecycle emitter is nil")
	case cfg.Jurisdiction == "":
		return nil, errors.New("nativemirror executor: jurisdiction is required")
	case cfg.ClaimedBy == "":
		return nil, errors.New("nativemirror executor: claimed-by identity is required")
	case !intents.CanPublishRegistrations():
		return nil, errors.New("nativemirror executor: intents store has no registry publisher; pass nativemirror.WithRegistryPublisher")
	}
	cfg = cfg.withDefaults()
	return &Executor{
		intents:  intents,
		registry: registry,
		bridge:   bridge,
		authz:    authz,
		seeder:   seeder,
		clusters: clusters,
		events:   events,
		cfg:      cfg,
	}, nil
}

// Run polls for claimable intents until ctx is done. Fits the serve-mode
// subsystem contract (func(ctx) error, exits only on cancellation).
func (e *Executor) Run(ctx context.Context) error {
	ticker := time.NewTicker(e.cfg.Interval)
	defer ticker.Stop()
	for {
		// Sampled before draining so the first sample lands at boot rather than
		// one interval later; a failure only warns and retries next tick.
		if err := e.RecordStageAges(ctx); err != nil {
			slogutil.Warn(ctx, "native-mirror executor: intent stage-age sample failed",
				slog.String("jurisdiction", e.cfg.Jurisdiction),
				slog.String("error", err.Error()))
		}
		// Drain the backlog: keep claiming until nothing is eligible.
		for {
			progressed, err := e.RunOnce(ctx)
			if err != nil {
				slogutil.Error(ctx, "native-mirror executor: pass failed", slog.String("error", err.Error()))
				break
			}
			if !progressed {
				break
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}
	}
}

// RecordStageAges samples this jurisdiction's unfinished intents and emits the
// stage-age gauge (COR-1271). Called on every Run tick: this loop is the one
// per-jurisdiction cadence already scoped to exactly these rows, so the signal
// needs no subsystem or configuration of its own — and it is the right scope,
// not just the convenient one, since ENTIRE_NATIVE_MIRROR_ENABLED must stay
// true while a jurisdiction holds an unconverged intent (see its config doc).
//
// Best-effort: the caller warns and the next tick retries, because a telemetry
// read must never stop intents from draining. A failed sample returns BEFORE
// the drained-series bookkeeping — a database error is not evidence that
// anything converged, and zeroing on it would report "nothing pending" for
// intents that are still there.
func (e *Executor) RecordStageAges(ctx context.Context) error {
	samples, err := e.intents.SampleIntentStageAges(ctx, e.cfg.Jurisdiction)
	if err != nil {
		return fmt.Errorf("sample intent stage ages: %w", err)
	}
	recordIntentStageAges(ctx, e.cfg.Jurisdiction, e.stageAges.withDrainedZeros(samples))
	return nil
}

// RunOnce claims at most one intent and drives it. Returns whether a row was
// claimed (progressed or retried) so Run can drain backlogs eagerly.
func (e *Executor) RunOnce(ctx context.Context) (bool, error) {
	row, ok, err := e.intents.Claim(ctx, e.cfg.ClaimedBy, e.cfg.Jurisdiction, e.cfg.Lease)
	if err != nil {
		return false, fmt.Errorf("claim: %w", err)
	}
	if !ok {
		return false, nil
	}
	if row.DesiredState == DesiredDeleted {
		if err := e.teardown(ctx, row); err != nil {
			if errors.Is(err, errStageLost) {
				if rerr := e.intents.Release(ctx, row.ID, e.cfg.ClaimedBy); rerr != nil {
					return true, fmt.Errorf("release after lost teardown fence: %w", rerr)
				}
				return true, nil
			}
			// Teardown is never marked permanently failed: it must converge or
			// account erasure (BeginPrimaryErasure) never drains. But a teardown
			// that keeps failing would otherwise be invisible, so past
			// StuckThreshold attempts emit an escalation the operator can alert
			// on — this is the recovery signal the v1 reconciler otherwise lacks.
			if row.Attempts >= e.cfg.StuckThreshold {
				slogutil.Error(ctx, "native-mirror executor: teardown stuck; manual recovery may be required (blocks account-erasure drain)",
					slog.String("placement_id", row.ID.String()),
					slog.String("cluster_slug", row.ClusterSlug),
					slog.String("stage", row.Stage),
					slog.Int64("attempts", row.Attempts),
					slog.String("error", err.Error()))
			} else {
				slogutil.Error(ctx, "native-mirror executor: teardown step failed; will retry",
					slog.String("placement_id", row.ID.String()),
					slog.String("stage", row.Stage),
					slog.String("error", err.Error()))
			}
			if rerr := e.intents.RecordRetry(ctx, row.ID, e.cfg.ClaimedBy, err.Error(), e.cfg.RetryBackoff); rerr != nil {
				return true, fmt.Errorf("record teardown retry: %w (after: %w)", rerr, err)
			}
		}
		return true, nil
	}
	if row.DesiredState != DesiredActive {
		return true, fmt.Errorf("unsupported desired state %q", row.DesiredState)
	}
	if err := e.execute(ctx, row); err != nil {
		// A lost fenced CAS is not a failure — the row moved under us
		// (deletion flipped mid-flight, or another executor won). Drop the
		// claim (fenced; a no-op if we no longer hold it) and let the next
		// claimer re-read. Crucially do NOT RecordRetry here: RecordRetry
		// would stamp a misleading last_error attributing the lost race to a
		// failure and bump attempts on a row we no longer own. (A deleted row
		// re-surfaces on the next drain iteration and is backed off there via
		// the non-active branch — so the deferral is a beat, not permanent;
		// the point is only that THIS lost CAS is not itself a failure.)
		if errors.Is(err, errStageLost) {
			slogutil.Info(ctx, "native-mirror executor: stage transition lost, releasing claim for re-read",
				slog.String("placement_id", row.ID.String()),
				slog.String("stage", row.Stage))
			if rerr := e.intents.Release(ctx, row.ID, e.cfg.ClaimedBy); rerr != nil {
				return true, fmt.Errorf("release after lost stage: %w", rerr)
			}
