package nativemirror

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"

	"entire.io/core/model"
)

// RequestStatus is the processing state of a native-mirror request.
type RequestStatus string

const (
	RequestPending    RequestStatus = "pending"
	RequestProcessing RequestStatus = "processing"
	RequestFailed     RequestStatus = "failed"
)

// RequestPublishHold is how long a publish holds off the sweep. It exceeds a
// job's whole JetStream retry chain, so the sweep republishes only a lost job.
const RequestPublishHold = 30 * time.Minute

// Request is one native_mirror_requests row: a native-mirror region that has
// no native_mirrors intent yet.
type Request struct {
	RepoID             model.RepoID
	ClusterSlug        string
	PlacementID        model.RepoID
	Jurisdiction       string
	CreatedByAccountID string
	Status             RequestStatus
	Attempts           int64
	LastError          string
	FailureCode        string
	FailureMessage     string
	NextPublishAt      time.Time
	FailedAt           *time.Time
	// CancelledAt is set when a user removed the region before its intent
	// existed. A job that was already running reads it back when it finishes,
	// and deletes the intent it just created.
	CancelledAt *time.Time
	// CancelledByAccountID is the account that cancelled the request, or
	// empty.
	CancelledByAccountID string
	// CancelSettledAt is set once the job of a cancelled request has removed
	// any intent stored under PlacementID.
	CancelSettledAt *time.Time
	CreatedAt       time.Time
}

// RequestPublisher queues a native_mirror_create job for a request and returns
// nil once the broker has accepted it.
type RequestPublisher interface {
	PublishRequest(ctx context.Context, request Request) error
}

