	"entire.io/slogutil"
)

const (
	ackWait           = 2 * time.Minute
	maxDeliver        = 5
	attemptTimeout    = 90 * time.Second
	durableNamePrefix = "entirecore-native-mirror-create-"
	dlqSubjectPrefix  = "repo.ops.dlq.v1.native_mirror_create."
	// exhaustedWait is when the sweep publishes a job again after its
	// JetStream deliveries ran out on retryable errors. The runner fails the
	// request once it has kept failing for a day.
	exhaustedWait = 10 * time.Minute
)

// retryPolicy spaces redeliveries 30 s, 1 min, 2 min, then 4 min apart.
var retryPolicy = backoff.Policy{NakDelay: 30 * time.Second, Factor: 2, MaxDelay: 4 * time.Minute, MaxDeliver: maxDeliver}

// RequestStore is the request state the consumer changes.
type RequestStore interface {
	StartRequestAttempt(ctx context.Context, repoID model.RepoID, clusterSlug string) (nativemirror.Request, bool, error)
	RecordRequestRetry(ctx context.Context, req nativemirror.Request, lastError string) (bool, error)
	RecordRequestWait(ctx context.Context, req nativemirror.Request, lastError string, wait time.Duration) (bool, error)
	RecordRequestFailure(ctx context.Context, req nativemirror.Request, code, message, lastError string) (bool, error)
}

// Runner makes one attempt at a request.
type Runner interface {
	Run(ctx context.Context, req nativemirror.Request) coreapi.NativeMirrorRequestOutcome
}

// Config contains the consumer dependencies.
type Config struct {
	Conn         *nats.Conn
	Store        RequestStore
	Runner       Runner
	DLQ          natsmsg.DLQPublisher
// Package nativemirrorcreate queues and runs native-mirror creation requests
// on the repo_ops_v1 stream. It follows internal/entirecore/mirrorcreate,
// which does the same for GitHub mirrors, with its own op and durable so a
// core that predates it never receives these jobs.
package nativemirrorcreate

import (
	"encoding/json"
	"errors"
	"fmt"

	"entire.io/core/model"
	"entire.io/internal/entirecore/repoops"
)

const (
	jobVersion = 1
	op         = "native_mirror_create"
)

type job struct {
	Version     int    `json:"version"`
	RepoID      string `json:"repo_id"`
	ClusterSlug string `json:"cluster_slug"`
}

// subjectFilter matches this op for every target cluster in jurisdiction.
// The subject's cluster token is the target cluster; the job runs in the
// primary's jurisdiction.
func subjectFilter(jurisdiction string) string {
	return repoops.SubjectPrefix + jurisdiction + ".*." + op
}

func unmarshalJob(data []byte) (job, model.RepoID, error) {
	var decoded job
	if err := json.Unmarshal(data, &decoded); err != nil {
		return job{}, model.RepoID{}, fmt.Errorf("unmarshal native-mirror-create job: %w", err)
	}
	if decoded.Version != jobVersion {
		return job{}, model.RepoID{}, fmt.Errorf("unknown native-mirror-create job version %d", decoded.Version)
	}
	if decoded.ClusterSlug == "" {
		return job{}, model.RepoID{}, errors.New("native-mirror-create job missing cluster_slug")
	}
	repoID, err := model.ParseRepoID(decoded.RepoID)
	if err != nil {
		return job{}, model.RepoID{}, fmt.Errorf("native-mirror-create job repo_id: %w", err)
	}
	return decoded, repoID, nil
}
