	RepoID      string `json:"repo_id"`
	ClusterSlug string `json:"cluster_slug"`
}

// subjectFilter matches this op for every target cluster in jurisdiction.
// The subject's cluster token is the target cluster; the job runs in the
// primary's jurisdiction.
func subjectFilter(jurisdiction string) string {
	return repoops.SubjectPrefix + jurisdiction + ".*." + op
}

func unmarshalJob(data []byte) (job, model.RepoID, error) {
	var decoded job
	if err := json.Unmarshal(data, &decoded); err != nil {
		return job{}, model.RepoID{}, fmt.Errorf("unmarshal native-mirror-create job: %w", err)
	}
	if decoded.Version != jobVersion {
		return job{}, model.RepoID{}, fmt.Errorf("unknown native-mirror-create job version %d", decoded.Version)
	}
	if decoded.ClusterSlug == "" {
		return job{}, model.RepoID{}, errors.New("native-mirror-create job missing cluster_slug")
	}
	repoID, err := model.ParseRepoID(decoded.RepoID)
	if err != nil {
		return job{}, model.RepoID{}, fmt.Errorf("native-mirror-create job repo_id: %w", err)
	}
