natsURL := os.Getenv("ENTIRE_NATS_URL")
if natsURL == "" {
	return errors.New("ENTIRE_NATS_URL is required")
}

// Consumer selection (COR-1021). The webhook consumer defaults ON — the
// binary must keep fanning US webhooks when it ships ahead of the fleet
// flag — and is switched off on non-US clusters, which have no
// webhooks_github_v1 stream to consume (an enabled consumer there would
// loop on "stream not found" and hold /readyz false forever). The
// native-mirror consumer defaults OFF so this binary ships inert; fleet
// enables it per cluster together with the routing map it needs.
webhookEnabled, err := parseBoolEnvFrom(os.Getenv, "FANOUT_WEBHOOK_CONSUMER_ENABLED", true)
if err != nil {
	return err
}
nativeMirrorEnabled, err := parseBoolEnvFrom(os.Getenv, "FANOUT_NATIVE_MIRROR_CONSUMER_ENABLED", false)
if err != nil {
	return err
}
if !webhookEnabled && !nativeMirrorEnabled {
	return errors.New("no consumer enabled: at least one of FANOUT_WEBHOOK_CONSUMER_ENABLED / FANOUT_NATIVE_MIRROR_CONSUMER_ENABLED must be true")
}

// Repo-lookup client talks to entire-core's internal mTLS listener over
// the workload PCA cert mounted by fleet's _lib/internal-tls. Both
// consumers resolve through it (webhook: LookupByMirror; native-mirror:
// LookupNativeMirrorsByRepoID), each behind its own read-through cache:
// short negative TTL so new mirrors activate quickly, longer positive
// TTL since placements rarely change.
lookupClient, err := mirrorjobs.NewRepoLookupClient(
	os.Getenv("ENTIRE_INTERNAL_TLS_CERT_FILE"),
	os.Getenv("ENTIRE_INTERNAL_TLS_KEY_FILE"),
	os.Getenv("ENTIRE_INTERNAL_TLS_CA_FILE"),
	os.Getenv("ENTIRE_CORE_INTERNAL_URL"),
)
if err != nil {
	return fmt.Errorf("init repo lookup client: %w", err)
}
var resolver *mirrorjobs.CoreLookupResolver
if webhookEnabled {
	cachedLookup := mirrorjobs.NewCachingRepoLookupClient(lookupClient, 60*time.Second, 5*time.Second)
	go cachedLookup.Run(ctx)
	resolver = mirrorjobs.NewCoreLookupResolver(cachedLookup)
}
var nativeResolver *mirrorjobs.NativeMirrorResolver
if nativeMirrorEnabled {
	cachedNativeLookup := mirrorjobs.NewCachingNativeMirrorLookupClient(lookupClient, 60*time.Second, 5*time.Second)
	go cachedNativeLookup.Run(ctx)
	nativeResolver = mirrorjobs.NewNativeMirrorResolver(cachedNativeLookup)
}

listenAddr := svchttp.ListenAddr(os.Getenv)

// Required so a multi-region rollout cannot accidentally share consumer
// state. JetStream durables are stream-scoped; if EU fanout starts
// consuming from the US upstream stream during a transition with the
// same durable name as US fanout, the two consumers share delivery
// cursor and redelivery state. Distinct durable per region (e.g.
// "fanout-us-east-2", "fanout-eu-central-1") is the cheapest safeguard.
// (The native-mirror consumer's durable is fixed instead: its stream is
// per-cluster local, so no two clusters can collide.)
durable := os.Getenv("FANOUT_DURABLE")
if webhookEnabled && durable == "" {
	return errors.New("FANOUT_DURABLE is required when the webhook consumer is enabled (e.g. fanout-us-east-2)")
}

// Multi-region NATS routing for mirror.git.v1.> publishes (see
// docs/multi-region/cross-region-nats-cutover.md). FANOUT_NATS_REGIONS
// is a comma-separated cluster_id=url list of REMOTE NATS clusters
// fanout should dial in addition to its local NATS. Empty = single-
// region mode (everything publishes to the local NATS, backward
// compatible). When set, FANOUT_LOCAL_CLUSTER_ID is required so the
// local connection is registered in the routing map under the right
// key; unknown cluster_ids in routes returned by Core then surface
// as publish errors (consumer Naks, operator fixes the map).
remoteRegions, err := natsregions.ParseConfig(os.Getenv("FANOUT_NATS_REGIONS"))
if err != nil {
	return fmt.Errorf("FANOUT_NATS_REGIONS: %w", err)
}
localClusterID := os.Getenv("FANOUT_LOCAL_CLUSTER_ID")
if err := natsregions.ValidateLocalClusterID(localClusterID, remoteRegions); err != nil {
	return fmt.Errorf("FANOUT_LOCAL_CLUSTER_ID: %w", err)
}
// The native-mirror consumer needs the local cluster identity even in
// single-region mode: it is the loop-prevention key — events whose home
// cluster isn't THIS cluster are dropped. Without it every mirror-side
// echo of a worker push would be indistinguishable from a home push.
if nativeMirrorEnabled && localClusterID == "" {
	return errors.New("FANOUT_LOCAL_CLUSTER_ID is required when the native-mirror consumer is enabled")
}
if nativeMirrorEnabled && len(remoteRegions) == 0 {
	// Legal (a single-cluster environment has no remotes) but worth a
	// loud note: with an empty region map every publish resolves to the
	// LOCAL NATS, so a sync job for a native mirror hosted on another
	// cluster would land on the local mirror_git_v1 where no worker
	// consumes its subject — it ages out silently after StreamMaxAge.
	slog.Warn("Native-mirror consumer enabled with no FANOUT_NATS_REGIONS: cross-cluster sync jobs would publish to LOCAL NATS and be dropped; fine only while no native mirrors exist for repos homed on this cluster (they are always cross-cluster)")
}

