// prepareFusedEvents builds the outbox rows for a fenced batch before the
// CAS, from the same inputs Outbox.Emit uses, and returns ctx carrying them
// so PostgresStore can insert each row inside the ref's CAS statement. It
// returns ctx unchanged and a nil carrier when nothing is to be fused: a sink
// that is not the transactional outbox, the legacy path, suppressed events,
// restore mode, no ambient transaction, or a batch with only trust refs,
// which produce no event. The RSL ref is inside refs/gittuf/** and is
// excluded with it. Rows are marshalled for every ref before the CAS knows
// which apply, so a ref the CAS rejects costs a wasted marshal, which is
// accepted. A marshal failure fails the batch, as Emit would, even for a ref
// whose CAS would have been rejected.
func (s *RecordingStore) prepareFusedEvents(ctx context.Context, repoID repositories.ID, commands []*packp.Command) (context.Context, *fusedEvents, error) {
	outbox, ok := s.events.(*refevents.Outbox)
	tx := pgutil.TxFromContext(ctx)
	if !ok || !outbox.Enabled() || tx == nil || !fencedPath(ctx) || RefEventsSuppressed(ctx) || IsRestoreMode(ctx) {
		return ctx, nil, nil
	}
	pusher := refevents.PusherFromContext(ctx)
	repoGroupID := reqctx.RepoGroupIDFromContext(ctx)
	now := time.Now()
	rows := make(map[plumbing.ReferenceName]outboxRow, len(commands))
	for _, c := range commands {
		name := c.Name.String()
		if refpolicy.InGittufNamespace(name) {
			continue
		}
		ch := refevents.Change{RefName: name, OldTarget: c.Old, NewTarget: c.New, Op: opFor(ctx, name, c.Old, c.New)}
