// Package refpolicy is the single source of truth for how entiredb treats the
// reserved and internal Git ref namespaces. It answers three questions that
// were previously decided in three places and drifted:
//
//   - Push: may this caller push this ref, or is the namespace reserved?
//     (was server/githttp/receive_pack.go's reservedPush* slices)
//   - Fetch: is this ref hidden from advertisement for this caller?
//     (uploadpack.hideRefs, previously wired nil everywhere)
//   - Recording: should a push to this ref produce a signed RSL entry?
//     (was rslstore.ShouldRecord's denylist)
//
// Recording starts from fetch visibility: a hidden ref is never signed. Two
// visible namespaces are carved out as well. Unmirrored branches
// (refs/heads/entire/unmirrored/*) stay visible on fetch but are never mirrored
// to GitHub, and git-sync's transfer scaffolding (refs/gitsync/**) stays visible
// so a bootstrap can resume but exists only on a replication target (see
// ShouldRecord). The coverage mode then narrows what remains to branches, tags,
// and checkpoints (see CoveredByMode). Deriving visibility and the recording
// base from one hidden set keeps a hidden ref from ever being signed.
//
// The policy is layered as a chain of command (see resolve): a base layer of
// fleet-wide invariants, then per-domain deltas (native vs GitHub-mirror repos),
// then per-caller carve-outs. Each layer may only ADD restrictions; the only
// ways to loosen are an explicit workload carve-out (push) or the trusted-reader
// exemption (fetch). Deny-by-default, fail-closed.
package refpolicy

import (
	"slices"
	"strings"

	"entire.io/core/servicetoken"
	"entire.io/internal/go-git/plumbing/transport/hiderefs"
	"github.com/gittuf/gittuf/pkg/rsl"
)

// Canonical ref namespaces. These names previously lived as unexported
// constants in receive_pack.go, rslstore/writer.go, and refstore; this package
// is now their one home.
const (
	// GittufPrefix is gittuf's reserved namespace (RSL, policy, policy-staging,
	// attestations). entiredb owns it server-side; direct client pushes to any
	// refs/gittuf/* are refused.
	GittufPrefix = "refs/gittuf/"
	// RSLRef is the gittuf Reference State Log, written server-side by rslstore.
	// Bound to gittuf's own constant so the recording carve-out (ShouldRecord)
	// cannot drift from the ref gittuf actually writes and start signing the RSL
	// into itself.
	RSLRef = rsl.Ref
	// PolicyStagingRef is gittuf's staging policy ref. gittuf keeps its own copy
	// unexported (unlike rsl.Ref), so this literal must be kept equal to it by
	// hand.
	PolicyStagingRef = "refs/gittuf/policy-staging"
	// PolicyRef is the repo's root of trust. It is client-visible so clients can
	// verify against it, so it is neither hidden nor exempt from recording.
	PolicyRef = "refs/gittuf/policy"

	// ManagedMetaPrefix is the git-meta service's shared metadata namespace,
	// reserved for direct client pushes but writable by the entire-api workload.
	// It is client-visible and recorded.
	ManagedMetaPrefix = "refs/meta/entire/"

	// InternalPrefix, LocalPrefix, and EntirePrefix are entiredb-internal
	// namespaces: reserved from direct client push, hidden from external fetch,
	// and not recorded. Two sub-namespaces below are exceptions on all three
	// counts, because a client owns each: EntireCheckpointsPrefix and
	// EntirePoliciesPrefix. refs/local/* holds node-local refs that never leave
	// the server, so they are never advertised and users cannot push them.
	InternalPrefix = "refs/internal"
	LocalPrefix    = "refs/local"
	EntirePrefix   = "refs/entire"

	// HeadsPrefix and TagsPrefix are the two ordinary user-facing namespaces.
	// They carry no policy of their own here. They exist so the coverage modes
	// in coverage.go name them from the same place as every other namespace
	// literal rather than re-spelling them.
	HeadsPrefix = "refs/heads/"
	TagsPrefix  = "refs/tags/"

	// GitSyncScaffoldPrefix is git-sync's own temp-ref namespace on a
	// replication TARGET: a batched bootstrap parks each branch at
	// refs/gitsync/bootstrap/heads/<branch> and removes it when the branch
	// lands. It is transfer scaffolding the sync writes and deletes itself, not
	// repository content, and it exists ONLY on the target — the primary never
	// holds one, so the primary's RSL never attests one.
	//
	// It is carved out of recording for that reason, and deliberately NOT hidden:
	// git-sync reads its own scaffolding back from the target's advertisement to
	// resume an interrupted bootstrap, so hiding it would break the resume.
	// See server/githttp's gitsyncScaffoldPrefix, which pins the same literal for
	// the writer-scope gate.
	GitSyncScaffoldPrefix = "refs/gitsync/"

	// EntireCheckpointsPrefix is the checkpoint sub-namespace of refs/entire. It
	// is the exception to the refs/entire rules: checkpoints are client-visible
	// (un-hidden), user-amendable (pushable), and therefore recorded, while the
	// rest of refs/entire stays hidden and reserved. refs/entire/checkpoints/* is
	// written both by the entire-api path (repoapi commit_create) and by users.
	EntireCheckpointsPrefix = "refs/entire/checkpoints"

	// EntirePoliciesPrefix is the checkpoint-policy sub-namespace of
	// refs/entire. The entire CLI owns it: checkpointpolicy.Push writes
	// refs/entire/policies/checkpoint, and the same package lists and fetches
	// that ref to compare a local policy against the remote baseline.
	//
