)
// knownReasons are the failure-index reasons emitted as depth_by_reason series.
// Listed explicitly (not derived from what's seen) so every series stays
// continuous: a reason absent this pass emits a 0 rather than letting the gauge
// go stale at its last non-zero value.
var knownReasons = []failindex.FailureReason{
	failindex.ReasonPermanent,
	failindex.ReasonMaxDeliveries,
	failindex.ReasonValidation,
	failindex.ReasonExternalBlocked,
}
// emitDepthByReason emits a complete scan, including zeros for absent reasons.
func emitDepthByReason(ctx context.Context, m *rekickMetrics, counts map[failindex.FailureReason]int) {
	for _, reason := range knownReasons {
		m.recordDepthByReason(ctx, string(reason), counts[reason])
	}
}
// maxConsecutiveErrors aborts a pass once this many entries in a row fail to
// read/publish — a systemic problem (a grant regression on mirror.git.v1.>, or
// NATS unavailable) rather than a one-off. Fails the pass fast (exit non-zero,
// loud) instead of grinding ~5s/entry through the whole cap; the next tick
// retries. Reset on any success/skip, so a healthy pass with the odd blip never
// trips it. This is a best-effort fast-fail, NOT the grant-regression alarm: a
// publish-only regression keeps Get() (a different grant) working, so organic
// heals (found=false) interleave and reset the counter — the pass then bottoms
// out at the deadline and exits 0. That's fine; rekicker_perm_denied fires on
// every denied publish regardless and IS the authoritative grant-regression signal.
const maxConsecutiveErrors = 20
// failIndexReader is the read surface the re-kick pass needs (a seam for tests;
// *failindex.Index satisfies it). Keys takes a ctx so the pass deadline / SIGTERM
// bounds the (otherwise unbounded) listing, not just the publish loop.
type failIndexReader interface {
	Keys(ctx context.Context) ([]string, error)
	Get(ulid string) (failindex.FailedSync, bool, error)
}
// publisher is the JetStream publish surface (a seam for tests;
// nats.JetStreamContext satisfies it).
type publisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
