const repoNameGitSuffix = ".git"

// NormalizeRepoName trims and validates a native repo name against the same
// shape as project names — lowercase letters, digits, '-', and interior '.'
// (e.g. "entire-trails.el"), no leading or trailing '-'/'.', no consecutive
// dots, not a raw ULID — differing only in length bounds, the dot allowance,
// and the trailing-".git" ban below. Rejecting uppercase at create time is
// what lets /et/ paths be folded to lowercase on resolution (see
// authn.CanonicalizeRepoURL) without collapsing two distinct repos: no new
// case-colliding pair can be created. Dots are safe because repo names
// resolve to a ULID and never become a filesystem path or git ref (objects
// are content-addressed by RepoID); the ".."/edge-dot bans keep names clean
// in URLs and clone output regardless.
//
// A trailing ".git" is the one dot case this refuses, in any case
// spelling. It is half of the canonical `.git` rule: the suffix is an
// alias on every transport path, never part of a name.
// coreclaims.TrimRepoPathGitSuffix is the other half and carries the full
// statement, including why Git LFS needs both.
//
// The check lives here, not in normalizeName. Project and org names pass
// allowDot=false, so they never reach the case.
func NormalizeRepoName(name string) (string, error) {
	// Refuse the suffix before the shape check. normalizeName rejects
	// uppercase, so a later check would answer "widgets.GIT" with the
	// charset rule and never name the suffix.
	trimmed := strings.TrimSpace(name)
	if before, ok := cutRepoNameGitSuffix(trimmed); ok {
		// Name the alternative only when it is itself a legal name.
		// ".git" leaves nothing and "WIDGETS.GIT" leaves an uppercase name.
		if suggestion, serr := normalizeName("repo name", before, repoNameMinLen, repoNameMaxLen, true); serr == nil {
			return "", fmt.Errorf("repo name %q must not end with %q; use %q: %w",
				trimmed, repoNameGitSuffix, suggestion, ErrInvalidName)
		}
		return "", fmt.Errorf("repo name %q must not end with %q: %w",
			trimmed, repoNameGitSuffix, ErrInvalidName)
	}
	return normalizeName("repo name", trimmed, repoNameMinLen, repoNameMaxLen, true)
}

// cutRepoNameGitSuffix removes a trailing ".git" in any case.
func cutRepoNameGitSuffix(name string) (string, bool) {
	if len(name) < len(repoNameGitSuffix) {
		return name, false
	}
	cut := len(name) - len(repoNameGitSuffix)
	if !strings.EqualFold(name[cut:], repoNameGitSuffix) {
		return name, false
	}
	return name[:cut], true
}

