// authorizeProjectRepoPlacements runs BEFORE any regional/visibility/metadata
// enrichment. Viewing a project shell says nothing about its repositories.
// Use placement permissions rather than group-only checks: native project and
// platform authority, and canonical-primary inheritance, live on repo objects.
// A specific name request must recheck stale denies, unlike a listing filter.
// The listing filter reads at snap's revision instead: a repo created inside
// the regional replica's window is in the caller's CockroachDB snapshot, so a
// stale deny drops it from the very page that created it. An absent revision
// keeps the ADR's stale list read.
func (s *RepoService) authorizeProjectRepoPlacements(ctx context.Context, accountID model.AccountID, placements []*resource.RepoRegistrationWithURL, snap committoken.Snapshot, specificRequest bool) ([]*resource.RepoRegistrationWithURL, error) {
	if len(placements) == 0 {
		return nil, nil
	}
	ids := make([]string, len(placements))
	for i, p := range placements {
		ids[i] = p.ID.String()
	}
	allowed, err := s.placementMetadataAllowed(ctx, accountID, ids, snap, specificRequest)
	if err != nil {
		// Every non-404 answer on this endpoint must be the same 503 during an
		// outage. projectRepoNameConflict already answers 503 here when a name
		// collides; a single hidden match failing this check must answer the
		// same status, or an outage would tell "one hidden repo" apart from
		// "colliding names" (COR-1865).
		slogutil.Error(ctx, "project repos: metadata authorization failed", slog.Any("error", err))
		return nil, authzUnavailable()
	}
	visible := make([]*resource.RepoRegistrationWithURL, 0, len(placements))
	for _, p := range placements {
		if allowed[p.ID.String()] {
			visible = append(visible, p)
		}
	}
	return visible, nil
}

func (s *RepoService) placementMetadataAllowed(ctx context.Context, accountID model.AccountID, ids []string, snap committoken.Snapshot, specificRequest bool) (map[string]bool, error) {
	permission := authz.Action(string(authz.ViewMetadata))
	var allowed map[string]bool
	var err error
	if specificRequest {
		allowed, err = s.ManageAuthority.gateBulkCan(ctx, authz.AllowStale, s.Server.Authz(), authz.RepoType, permission, authz.AccountSubjectType, accountID.String(), ids)
	} else {
		// RevisionFromToken maps an absent revision to RevisionAbsent, never the
		// zero Revision this method would reject.
		allowed, err = s.ManageAuthority.gateBulkCheckPermissionAtLeastAsFresh(ctx, s.Server.Authz(), authz.RevisionFromToken(snap.Revision),
			authz.RepoType, permission, authz.AccountSubjectType, accountID.String(), ids)
	}
	if err != nil {
		return nil, fmt.Errorf("placement metadata check: %w", err)
	}
	return allowed, nil
}

