// Processing-cell outcomes, recorded on mirrorrequest.processing_cell_outcomes_total.
const (
	processingCellDisabled    = "disabled"
	processingCellUnassigned  = "processing_cell_unassigned"
	processingCellSameCell    = "same_cell"
	processingCellPresent     = "processing_cell_present"
	processingCellAdopted     = "processing_cell_adopted"
	processingCellAbandoned   = "processing_cell_abandoned"
	processingCellUnavailable = "processing_cell_unavailable"
	processingCellQueued      = "queued"
	processingCellJoined      = "joined"
	processingCellQueueFailed = "queue_failed"
	processingCellConfirmed   = "processing_cell_confirmed"
	processingCellChanged     = "processing_cell_changed"
)

var (
	processingCellMetricsOnce sync.Once
	processingCellOutcomes    metric.Int64Counter
)

func recordProcessingCellOutcome(ctx context.Context, jurisdiction, outcome string) {
	processingCellMetricsOnce.Do(func() {
		var err error
		processingCellOutcomes, err = otel.Meter("entire.io/core/api").Int64Counter(
			"mirrorrequest.processing_cell_outcomes_total",
			metric.WithDescription("Primary processing cell decisions of the mirror-request consumer by jurisdiction (COR-1543)."),
			metric.WithUnit("{decision}"),
		)
		if err != nil {
			slogutil.Error(context.Background(), "register processing cell outcome metric failed", slog.Any("error", err))
		}
	})
	trace.SpanFromContext(ctx).SetAttributes(attribute.String("mirror_request.processing_cell", outcome))
	if processingCellOutcomes != nil {
		processingCellOutcomes.Add(ctx, 1, metric.WithAttributes(
			attribute.String("jurisdiction", jurisdiction),
			attribute.String("outcome", outcome),
		))
	}
}

// checkMirrorRequestProcessingCell runs after the mirrors project exists and
// before the placement is written. A user request for another cell queues a
// placement in the primary processing cell. A processing-cell request proceeds
// only while its cell is still that cell, so a stale request cannot place a
// mirror elsewhere.
func (s *Server) checkMirrorRequestProcessingCell(ctx context.Context, request mirrorrequest.Request, githubRepoID int64, cell string, project *model.Project) error {
	processingCell, err := s.mirrorProcessingCell(ctx, githubRepoID, project)
