// IsFinalMirrorRequestDelivery reports whether ctx carries that mark.
func IsFinalMirrorRequestDelivery(ctx context.Context) bool {
	final, ok := ctx.Value(finalMirrorRequestDeliveryKey{}).(bool)
	return ok && final
}

// ensureMirrorProcessingCell queues a request for the project's primary
// processing cell beside a user request for another cell. It runs before the
// user's placement is written and before the attempt records success, so a
// redelivery repeats it. The queued request runs as the same user; core picks
// the cell.
func (s *Server) ensureMirrorProcessingCell(ctx context.Context, request mirrorrequest.Request, githubRepoID int64, cell, processingCell string, project *model.Project) error {
	switch {
	case !s.mirrorEnsureProcessingCell:
		recordProcessingCellOutcome(ctx, s.jurisdiction, processingCellDisabled)
		return nil
	case processingCell == "":
		// An unassigned project awaits COR-1546; no request derives a cell.
		recordProcessingCellOutcome(ctx, s.jurisdiction, processingCellUnassigned)
		return nil
	case processingCell == cell:
		recordProcessingCellOutcome(ctx, s.jurisdiction, processingCellSameCell)
		return nil
	case s.mirrorRequests == nil || s.mirrorRequestPublisher == nil:
		return InternalMirrorRequestFailure(errors.New("mirror request queue not configured"))
	}

	present, err := s.mirrorRepos.HasPlacementInCell(ctx, githubRepoID, processingCell)
	if err != nil {
		return InternalMirrorRequestFailure(fmt.Errorf("find processing cell placement: %w", err))
	}
	if present {
		recordProcessingCellOutcome(ctx, s.jurisdiction, processingCellPresent)
		return nil
	}

	target, err := s.cluster.PlacementForCell(ctx, processingCell)
	if errors.Is(err, cluster.ErrNotFound) || errors.Is(err, cluster.ErrAmbiguousCell) {
		// A retry cannot fix the cluster registry. The user's placement goes
		// ahead; with election limited to the cell, the group has no
		// processing primary until the registry names a cluster.
		recordProcessingCellOutcome(ctx, s.jurisdiction, processingCellUnavailable)
		slogutil.Error(ctx, "mirror request: cluster registry names no cluster for the primary processing cell; placement not queued",
			slog.String("mirror_request_id", request.ID.String()),
			slog.String("project_id", project.ID.String()),
			slog.String("processing_cell", processingCell),
			slog.Any("error", err))
		return nil
	}
	if err != nil {
		return InternalMirrorRequestFailure(fmt.Errorf("resolve processing cell cluster: %w", err))
	}

	result, err := s.mirrorRequests.Submit(ctx, mirrorrequest.CreateParams{
		Provider:     request.Provider,
		Owner:        request.Owner,
		Repo:         request.Repo,
		ClusterSlug:  target.Slug,
		Jurisdiction: target.Jurisdiction,
		AccountID:    request.AccountID,
		GitHubUserID: request.GitHubUserID,
		Origin:       mirrorrequest.OriginEnsureProcessingCell,
	}, s.mirrorRequestPublisher)
	if err != nil {
		recordProcessingCellOutcome(ctx, s.jurisdiction, processingCellQueueFailed)
		return InternalMirrorRequestFailure(fmt.Errorf("queue processing cell placement on %q: %w", target.Slug, err))
	}
	outcome := processingCellJoined
