		outcome = processingCellQueued
	}
	recordProcessingCellOutcome(ctx, s.jurisdiction, outcome)
	slogutil.Info(ctx, "mirror request: processing cell placement queued",
		slog.String("mirror_request_id", request.ID.String()),
		slog.String("processing_cell_request_id", result.Request.ID.String()),
