// Waker signals the local relay to drain the outbox now, after a push commits,
// so delivery is a post-commit goroutine hop rather than the poll interval; the
// DefaultRelayInterval ticker falls back to a missed-message safety net.
//
// Best-effort and per-node: a wake reaches only the committing node's relay,
// which drains a shard only if it can take that shard's advisory lock. Rows a
// wake misses (crash before drain, a shard another node is mid-draining) wait
// for the fallback tick. The drain path is unchanged, so ordering and
// at-least-once still hold — the wake only moves the common case off the timer.
type Waker struct {
	ch chan struct{}
}

// NewWaker returns a Waker whose channel coalesces pending wakes.
func NewWaker() *Waker {
	return &Waker{ch: make(chan struct{}, 1)}
}

